document.addEventListener('DOMContentLoaded', function () {

    const table = document.querySelector('.table'); // your table class
    const popupID = 8020; // Elementor popup ID
    let isBlurred = true;

    if (!table) {
        console.error('Table not found! Check class .table');
        return;
    }

    // 🔹 Initial blur
    table.style.filter = 'blur(8px)';
    table.style.transition = 'filter 0.4s ease';
    table.style.cursor = 'pointer';

    // 🔹 Open Elementor popup
    function openPopup(e) {
        e.preventDefault();

        if (typeof elementorProFrontend !== 'undefined') {
            elementorProFrontend.modules.popup.showPopup({ id: popupID });
        } else {
            console.error('Elementor popup not loaded');
        }
    }

    // Click + mobile touch
    table.addEventListener('click', openPopup);
    table.addEventListener('touchstart', openPopup, { passive: false });

    // 🔹 Remove blur + close popup
    function unblurAndClosePopup() {
        if (isBlurred) {
            table.style.filter = 'none';
            table.classList.add('unlocked'); // for CSS overlay
            isBlurred = false;
        }

        if (typeof elementorProFrontend !== 'undefined') {
            elementorProFrontend.modules.popup.closePopup({ id: popupID });
        }
    }

    // ✅ BEST: CF7 success event
    document.addEventListener('wpcf7mailsent', function () {
        unblurAndClosePopup();
    });

    // ✅ Backup fallback
    document.addEventListener('wpcf7submit', function () {
        setTimeout(unblurAndClosePopup, 1500);
    });

});